<script setup>
import {ref,reactive,computed,onMounted,onUnmounted,watch} from 'vue';import {native,api,on,state} from './native.js';import Icon from './Icon.vue';import AppSelect from './AppSelect.vue';import AppOverlay from './AppOverlay.vue';import ChoiceRows from './ChoiceRows.vue';
import PlayCalendar from './PlayCalendar.vue';
const props=defineProps({openRiskOnEntry:Boolean,playtimeRequest:Object});
const emit=defineEmits(['risk-opened']);
const engine=ref({phase:'idle',installed:false,riskAccepted:false}),servers=ref([]),error=ref(''),busy=ref(''),showRisk=ref(false),showProfiles=ref(false),switchTarget=ref(''),advanced=ref(false),componentOpen=ref(false),refreshing=ref(false);
const moduleReady=computed(()=>!!(engine.value.installed||engine.value.ready));
const rendererOptions=computed(()=>[{value:'auto',label:'自动（FCL NG · GPU 直出）'},{value:'ng-gl4es',label:'NG-GL4ES · FCL 渲染器'},...(Array.isArray(engine.value.renderers)?engine.value.renderers:[]).filter(v=>['zink','softpipe'].includes(v.id)).map(v=>({value:v.id,label:v.label||v.id}))]);
const downloading=computed(()=>engine.value.phase==='downloading');
let saved={};try{saved=JSON.parse(localStorage.getItem('hxz-mobile-game')||'{}');}catch{}
const options=reactive({memoryMB:[0,1024,2048,3072,4096,6144].includes(saved.memoryMB)?saved.memoryMB:0,extendedMemory:saved.extendedMemory===true,renderer:['auto','ng-gl4es','softpipe','zink'].includes(saved.renderer)?saved.renderer:'auto',concurrency:[4,8,16,32].includes(saved.concurrency)?saved.concurrency:32,autoUpdate:saved.autoUpdate!==false,autoJoin:saved.autoJoin!==false});
watch(options,v=>localStorage.setItem('hxz-mobile-game',JSON.stringify(v)));const unsubscribe=on('gameEngine',v=>engine.value=v);
async function refresh(){if(refreshing.value)return;refreshing.value=true;error.value='';try{const [e,s]=await Promise.allSettled([native('gameEngine'),api('/api/server-presets')]);if(e.status==='fulfilled')engine.value=e.value;if(s.status==='fulfilled')servers.value=s.value.servers||[];const errors=[e,s].filter(v=>v.status==='rejected').map(v=>v.reason.message);if(errors.length)error.value=errors.join('；');}finally{refreshing.value=false;}}
let pendingAction=null;
async function action(name,values={}){error.value='';if(!engine.value.riskAccepted&&!['accept','state','cancel'].includes(name)){pendingAction={name,values};showRisk.value=true;return false;}if(!state.selectedProfile?.id&&!['accept','state','cancel'].includes(name)){showProfiles.value=true;return false;}busy.value=values.id||name;try{engine.value=await native('gameEngine',{action:name,...values});return true;}catch(e){error.value=e.message;return false;}finally{busy.value='';}}
function closeProfiles(){showProfiles.value=false;switchTarget.value='';}
async function changeProfile(id){if(id===state.selectedProfile?.id){closeProfiles();return;}if(state.room||state.recoveringRoom){switchTarget.value=id;return;}await confirmProfile(id);}
async function confirmProfile(id){busy.value='profile';error.value='';try{Object.assign(state,await native('profile',{id}));closeProfiles();await refresh();}catch(e){error.value=e.message;}finally{busy.value='';}}
async function manageProfiles(){try{await native('openSkin');}catch(e){error.value=e.message;}}
function closeRisk(){pendingAction=null;showRisk.value=false;}
function openRisk(){pendingAction=null;showRisk.value=true;}
async function accept(){if(!await action('accept',{accepted:true}))return;const pending=pendingAction;pendingAction=null;showRisk.value=false;if(pending)await action(pending.name,pending.values);}
const size=v=>(Math.max(0,v||0)/1024/1024).toFixed(1)+' MB';
onMounted(()=>{if(props.openRiskOnEntry){showRisk.value=true;emit('risk-opened');}void refresh();});onUnmounted(()=>{pendingAction=null;unsubscribe();});
</script>
<template><section class="content-page mobile-minecraft">
 <header class="page-toolbar"><h1>Minecraft</h1><button class="icon-button" aria-label="刷新游戏配置" :disabled="refreshing" @click="refresh"><Icon name="refresh"/></button></header>
 <div v-if="error" class="game-error" role="alert"><p>{{error}}</p><button class="soft-button" :disabled="refreshing" @click="refresh"><Icon name="refresh"/>重新检查</button></div>
  <p v-if="!state.hasAccount" class="game-login-note"><Icon name="user"/><span>在「我的」登录幻想镇皮肤站并选择角色后，即可准备游戏资源并进入服务器。</span></p>
  <p v-else-if="!state.selectedProfile?.id" class="game-login-note"><Icon name="user"/><span>请先选择游戏角色，再准备资源或进入服务器。 <button class="text-button" @click="showProfiles=true">选择角色</button></span></p>
 <div class="server-section-heading"><h2>选择服务器</h2><span class="muted">{{servers.length?servers.length+' 个默认服务器':'获取服务器配置'}}</span></div>
 <div v-if="!servers.length" class="card game-server-empty"><p>{{refreshing?'正在获取服务器…':'暂未取得服务器配置'}}</p><button v-if="!refreshing" class="soft-button" @click="refresh">重新获取</button></div>
  <div class="game-server-list"><article v-for="(server,index) in servers" :key="server.id" class="card mobile-server-card"><div class="engine-heading"><span class="server-number">{{String(index+1).padStart(2,'0')}}</span><div><h2>{{server.name}}</h2><p>{{server.profileSource==='hxzup'?'随服务器整合包更新':[server.version,server.loader||'原版'].filter(Boolean).join(' · ')}}</p></div></div><p v-if="!server.enabled" class="muted">服务器当前未开放</p><p v-else-if="server.updateRequired" class="muted">启动前需要完成服务器更新</p><div class="server-actions"><button class="primary" :disabled="!state.selectedProfile?.id||!server.enabled||!!busy||engine.busy" @click="action('launch',{id:server.id,options:{...options}})"><Icon name="play"/>{{busy===server.id?'正在准备…':moduleReady?'开始游戏':'准备并进入'}}</button></div></article></div>
 <PlayCalendar :request="playtimeRequest"/>
 <section class="card engine-status"><button class="engine-settings-trigger" :aria-expanded="componentOpen" @click="componentOpen=!componentOpen"><div><h2>游戏运行模块</h2><p>{{engine.busy?(engine.message||'正在准备游戏运行资源'):engine.phase==='error'?'准备失败，可继续下载':engine.phase==='paused'?'下载已暂停，可继续下载':moduleReady?'已就绪'+(engine.version?' · '+engine.version:''):engine.message||'首次启动时自动下载运行资源'}}</p></div><Icon name="chevron" :class="{'engine-chevron-open':componentOpen}"/></button>
  <div v-if="engine.busy" class="engine-download" aria-live="polite"><progress v-if="downloading&&engine.total>0" :value="engine.received||0" :max="engine.total"/><progress v-else aria-label="正在准备游戏运行资源"/><p>{{downloading&&engine.total>0?size(engine.received)+' / '+size(engine.total):engine.message||'正在准备游戏运行资源…'}}</p><button v-if="downloading" class="soft-button" :disabled="!!busy" @click="action('cancel')">暂停下载</button></div>
  <p v-if="engine.phase==='error'||engine.phase==='paused'" class="runtime-message" :class="{'is-error':engine.phase==='error'}" role="status">{{engine.message}}</p>
   <div v-if="componentOpen" class="engine-component-options"><p class="muted">运行模块在社区应用内启用。首次启动会自动准备；登录的社区角色会自动传给游戏。</p><div class="component-actions"><button class="primary" :disabled="!state.selectedProfile?.id||!!busy||engine.busy" @click="action('download')"><Icon name="download"/>{{engine.phase==='paused'||engine.phase==='error'?'继续下载':moduleReady?'检查模块更新':'预先下载运行模块'}}</button><button class="soft-button" :disabled="!state.selectedProfile?.id||!!busy||engine.busy" @click="action('settings')"><Icon name="settings"/>触控与高级设置</button><button class="soft-button" :disabled="!state.hasAccount||!!busy||engine.busy" @click="showProfiles=true"><Icon name="user"/>选择游戏角色</button><button class="soft-button" @click="openRisk">运行提示</button></div></div>
 </section>
 <section class="card mobile-runtime-settings"><button class="engine-settings-trigger" :aria-expanded="advanced" @click="advanced=!advanced"><div><h2>运行设置</h2><p>内存、渲染器与自动更新</p></div><Icon name="chevron" :class="{'engine-chevron-open':advanced}"/></button><div v-if="advanced" class="runtime-options"><label>内存分配<AppSelect v-model="options.memoryMB" label="游戏内存" :options="[{value:0,label:'自动分配'},... [1024,2048,3072,4096,6144].map(v=>({value:v,label:(v/1024)+' GB'}))]"/></label><label class="engine-switch"><span>使用交换内存（扩展预算）</span><input v-model="options.extendedMemory" type="checkbox"></label><p class="muted memory-hint">默认关闭，下次启动游戏生效。开启后允许利用系统已有的空闲交换空间适度提高内存上限；可能增加卡顿，不能代替物理内存。关闭后按物理内存预算分配，Android 仍可能自行换页。</p><label>渲染器<AppSelect v-model="options.renderer" label="渲染器" :options="rendererOptions"/></label><label>同时下载的文件<AppSelect v-model="options.concurrency" label="下载并发" :options="[4,8,16,32].map(v=>({value:v,label:v+' 个文件'}))"/></label><label class="engine-switch"><span>启动前更新整合包</span><input v-model="options.autoUpdate" type="checkbox"></label><label class="engine-switch"><span>启动后自动进入服务器</span><input v-model="options.autoJoin" type="checkbox"></label></div></section>
 <AppOverlay :open="showRisk" label="手机游戏运行提示" kind="confirm" @close="closeRisk"><section class="sheet engine-risk-dialog"><header class="sheet-header"><h2>手机游戏运行提示</h2><button class="icon-button" aria-label="关闭" @click="closeRisk"><Icon name="close"/></button></header><div class="sheet-body engine-risk-body"><p>游戏运行模块在幻想镇社区应用内启用，需要 ARM64 手机，无需另装应用。</p><ul><li>电脑模组不保证支持手机，大型整合包可能无法启动。</li><li>首次准备会下载游戏和运行资源；建议连接 Wi-Fi，预留足够存储与内存。</li><li>游戏可能发热、耗电或被系统回收。提高内存不一定更快。</li><li>登录的社区角色会由应用自动传给游戏。</li><li>新游戏世界保存在社区应用私有空间；旧版独立引擎中的存档不会自动迁移，也不会因此删除。卸载社区应用前请先备份世界。</li></ul><p v-if="error" class="error-note" role="alert">{{error}}</p><button class="primary" :disabled="!!busy" @click="accept">了解并启用</button></div></section></AppOverlay>
  <AppOverlay :open="showProfiles" label="选择游戏角色" kind="picker" @close="closeProfiles"><section class="sheet"><header class="sheet-header"><h2>选择游戏角色</h2><button class="icon-button" aria-label="关闭角色选择" @click="closeProfiles"><Icon name="close"/></button></header><div class="sheet-body profile-choices"><p v-if="error" class="error-note" role="alert">{{error}}</p><template v-if="switchTarget"><p>切换角色会离开当前语音房间，继续吗？</p><button class="primary" :disabled="!!busy" @click="confirmProfile(switchTarget)">继续切换</button><button class="soft-button" @click="switchTarget=''">返回角色列表</button></template><template v-else><p v-if="!state.profiles.length" class="muted">账号还没有角色，请先在皮肤站创建。</p><ChoiceRows :items="state.profiles.map(p=>({value:p.id,label:p.name}))" :value="state.selectedProfile?.id" label="选择游戏角色" @choose="changeProfile"/><button class="soft-button" @click="manageProfiles">创建或管理角色</button></template></div></section></AppOverlay>
</section></template>
<style scoped>
.mobile-minecraft{display:flex;flex-direction:column;gap:16px}.mobile-minecraft>*{flex:none;min-width:0}.mobile-minecraft>.card,.mobile-minecraft p,.mobile-minecraft h2{margin:0}.mobile-minecraft h2{font-size:1rem;line-height:1.6;word-break:normal;overflow-wrap:anywhere}.mobile-minecraft>.page-toolbar{padding-bottom:0;flex-wrap:wrap}.game-login-note{display:flex;align-items:flex-start;gap:10px;color:var(--muted);font-size:.86rem;line-height:1.7}.game-login-note>.icon{flex:none;margin-top:3px}.game-login-note>span{min-width:0}.server-section-heading{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:6px 12px}.server-section-heading>.muted{font-size:.78rem}.game-server-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:14px}.mobile-server-card{display:grid;gap:14px;align-content:start;margin:0}.engine-heading{display:flex;gap:12px;align-items:flex-start;min-width:0}.engine-heading>div{min-width:0;flex:1}.engine-heading p{margin-top:5px;color:var(--muted);overflow-wrap:anywhere;line-height:1.6;font-size:.86rem}.server-number{font-weight:650;font-variant-numeric:tabular-nums;font-size:1.1rem;color:var(--accent);background:var(--accent-soft);width:36px;height:36px;display:grid;place-items:center;border-radius:10px;flex:none}.server-actions{display:flex;flex-wrap:wrap;gap:10px}.server-actions>button{min-height:46px;min-width:0}.server-actions>.primary{flex:2 1 10.5em}.server-actions>.soft-button{flex:1 1 5.5em}.engine-status,.mobile-runtime-settings{display:grid;gap:14px}.engine-settings-trigger{display:flex;gap:12px;align-items:center;justify-content:space-between;background:none;border:0;padding:0;color:inherit;text-align:left;min-height:44px;width:100%}.engine-settings-trigger>div{min-width:0;flex:1}.engine-settings-trigger p{font-size:.82rem;color:var(--muted);line-height:1.7;margin-top:4px;overflow-wrap:anywhere}.engine-settings-trigger>.icon{flex:none}.engine-chevron-open{transform:rotate(90deg)}.engine-component-options,.runtime-options{display:grid;gap:16px;min-width:0}.component-actions{display:flex;flex-wrap:wrap;gap:10px}.component-actions>button{flex:1 1 160px;min-width:0;min-height:44px}.runtime-options>label{display:grid;gap:8px;min-width:0;font-size:.9rem;line-height:1.6}.runtime-options :deep(.app-select){min-width:0;width:100%}.runtime-options .engine-switch{display:flex;gap:16px;justify-content:space-between;align-items:center}.engine-switch>span{min-width:0}.engine-switch input{width:24px;height:24px;flex:none;min-height:24px}.engine-download{display:grid;gap:12px;min-width:0}.engine-download p{font-size:.85rem;line-height:1.6;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.mobile-minecraft progress{width:100%;max-width:100%;height:8px;accent-color:var(--accent)}.game-error,.runtime-message{padding:14px;border:1px solid var(--danger);background:var(--danger-bg);border-radius:12px;line-height:1.7;color:var(--danger);overflow-wrap:anywhere}.runtime-message{border-color:var(--line);background:var(--soft);color:var(--muted)}.runtime-message.is-error{border-color:var(--danger);background:var(--danger-bg);color:var(--danger)}.game-error{display:grid;gap:12px}.game-error>button{justify-self:start;min-height:44px}.game-server-empty{display:grid;gap:12px}.game-server-empty p{line-height:1.7}.engine-risk-dialog{border-radius:24px;overflow:hidden}.engine-risk-body{display:grid;gap:16px}.engine-risk-body p{line-height:1.7}.engine-risk-body ul{margin:0;padding-left:20px;line-height:1.7}.engine-risk-body li+li{margin-top:10px}.engine-risk-body .primary{min-height:46px;white-space:normal}.profile-choices{display:grid;gap:14px}.profile-choices>p{line-height:1.7}.profile-choices>button{min-height:44px}
</style>
